#if defined(ESP32)
struct servos_canal { bool activo; };
inline void servos_mover(servos_canal& servo, int pin, float angulo, const char* bloque) {
    if (!servo.activo) {
        if (!ledcAttach(pin, 50, 14)) { rb_fail(bloque, "No se pudo activar el servo"); return; }
        servo.activo = true;
    }
    angulo = fmaxf(0, fminf(180, rb_finite(angulo, bloque)));
    int pulso = int(500 + angulo * 2000 / 180);
    ledcWrite(pin, uint32_t(pulso) * 16383UL / 20000UL);
}
#else
inline void servos_mover(Servo& servo, int pin, float angulo, const char* bloque) {
    if (!servo.attached()) servo.attach(pin, 500, 2500);
    if (!servo.attached()) { rb_fail(bloque, "No se pudo activar Servo.h"); return; }
    angulo = fmaxf(0, fminf(180, rb_finite(angulo, bloque)));
    servo.writeMicroseconds(int(500 + angulo * 2000 / 180));
}
#endif

